"""Builds the PLUG brand SVG masters (direction D, "Ask P", chosen 2026-11-17).
Usage: python3 design/brand/build-masters.py design/brand "#2B1D14" "#FFF4EC" "#1F4D3A" "#A9793A"
(ink.900, paper, brand.green, brand.brass)"""
import re, sys, pathlib

if len(sys.argv) != 6 or not all(re.fullmatch(r"#[0-9A-Fa-f]{6}", c) for c in sys.argv[2:6]):
    sys.exit('usage: build-masters.py <out-dir> <ink> <paper> <green> <brass>, e.g. design/brand "#2B1D14" "#FFF4EC" "#1F4D3A" "#A9793A"')
out = pathlib.Path(sys.argv[1]); INK, PAPER, GREEN, BRASS = sys.argv[2:6]

# The mark: an open P that is also a question mark. One stroke width (36) and one radius pair:
# the bowl is a 270 degree arc, outer radius 62 and inner 26, centred at (129, 91) on a 256
# grid; the stem runs x 67..103. The brass dot under the stem is the asker.
def p(stem_end):
    return f"M67 {stem_end}V91A62 62 0 1 1 129 153V117A26 26 0 1 0 103 91V{stem_end}Z"
def dot(cy, r):
    return f"M{85 - r} {cy}A{r} {r} 0 1 0 {85 + r} {cy}A{r} {r} 0 1 0 {85 - r} {cy}Z"
MARK = (p(161), dot(204, 21))      # gap 22 between stem and dot
SMALL = (p(150), dot(207, 24))     # 24 px and below: shorter stem, bigger dot, gap 33, so the dot stays apart at 16 px

def mark_body(fill, dot_fill=None, small=False):
    letter, point = SMALL if small else MARK
    return f'<path fill="{fill}" d="{letter}"/><path fill="{dot_fill or fill}" d="{point}"/>'

