def word_body(fill):
    return (f'<g transform="translate(235.90 177.00) scale(0.15926)">'
            + "".join(f'<path fill="{fill}" d="{d}"/>' for d in WORD) + "</g>")

def svg(vb, body, title="PLUG"):
    return (f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="{vb}" role="img" aria-label="{title}">'
            f'<title>{title}</title>{body}</svg>\n')

# The logotype is cropped to its ink (x 64..524, y 29..225) plus an 8 unit margin, so it aligns
# with the text column and sizes by its own height.
LOGO = "56 21 476 212"
def icon(bg, mark):
    # Mark centred in the iOS safe area at 62% of the tile.
    return svg("0 0 1024 1024", f'<rect width="1024" height="1024" fill="{bg}"/><g transform="translate(194.56 194.56) scale(2.48)">{mark}</g>')

files = {
    "plug-mark.svg": svg("0 0 256 256", mark_body(GREEN, BRASS)),
    "plug-mark-small.svg": svg("0 0 256 256", mark_body(GREEN, BRASS, small=True)),
    "plug-mark-reversed.svg": svg("0 0 256 256", f'<rect width="256" height="256" fill="{INK}"/>' + mark_body(PAPER, BRASS)),
    "plug-mark-mono.svg": svg("0 0 256 256", mark_body("#000000")),
    "plug-logotype.svg": svg(LOGO, mark_body(GREEN, BRASS) + word_body(INK)),
    "plug-logotype-reversed.svg": svg(LOGO, f'<rect x="56" y="21" width="476" height="212" fill="{INK}"/>' + mark_body(PAPER, BRASS) + word_body(PAPER)),
    "plug-logotype-mono.svg": svg(LOGO, mark_body("#000000") + word_body("#000000")),
    # App icons: cream mark and brass dot on forest green (light) or espresso (dark); one colour
    # for tinted, which the system recolours.
    "app-icon.svg": icon(GREEN, mark_body(PAPER, BRASS)),
    "app-icon-dark.svg": icon(INK, mark_body(PAPER, BRASS)),
    "app-icon-tinted.svg": icon("#000000", mark_body("#FFFFFF")),
}
for name, text in files.items():
    (out / name).write_text(text)
print("wrote", ", ".join(files))
